import {controller, target} from '@github/catalyst'
import {SinglePageWizardStepContentBase} from '../../single-page-wizard/step-content-base'
import type {TwoFactorWizardState} from './wizard-state'

@controller('two-factor-setup-add-methods')
export class TwoFactorSetupAddMethodsElement extends SinglePageWizardStepContentBase {
  @target declare showU2fRegButton: HTMLButtonElement
  @target declare showU2fEnabledLabel: HTMLSpanElement
  #u2FRegistrationObserver!: MutationObserver

  override connectedCallback() {
    // stepContent attribute was not set in step-content-base.ts
    this.setAttribute('data-target', 'single-page-wizard-step.stepContent')

    const u2fRegistrations = document.querySelector('.js-u2f-registrations') as HTMLElement
    document.querySelector('#add-two-factor-u2f-registration')?.setAttribute('hidden', 'true')

    // on initial load, if there are already security keys registered, show enabled label
    if (u2fRegistrations.childElementCount > 0) {
      this.showU2fEnabledLabel.removeAttribute('hidden')
    }

    // Create an observer to watch for security key registrations being added or removed
    this.#u2FRegistrationObserver = new MutationObserver(mutations => {
      for (const mutation of mutations) {
        if (mutation.type === 'childList') {
          if (mutation.addedNodes.length > 0) {
            this.showU2fEnabledLabel.removeAttribute('hidden')
          } else if (mutation.removedNodes.length > 0 && u2fRegistrations.childElementCount === 0) {
            this.showU2fEnabledLabel.setAttribute('hidden', 'true')
          }
        }
      }
    })
    this.#u2FRegistrationObserver.observe(u2fRegistrations, {childList: true})

    this.showU2fRegButton.addEventListener('click', () => {
      document.querySelector('#add-two-factor-u2f-registration')?.removeAttribute('hidden')
      this.showU2fRegButton.setAttribute('hidden', 'true')
    })
  }

  disconnectedCallback() {
    this.#u2FRegistrationObserver.disconnect()
  }

  override async setStepState(wizardState: TwoFactorWizardState) {
    const {type} = wizardState

    // When the success banner is shown on the last step, we want to move focus to the banner
    // to ensure screen readers read the banner message, and to manage focus because it's otherwise lost.
    const wizardStepBanner = document.querySelector<HTMLElement>('.wizard-step-banner')
    setTimeout(() => wizardStepBanner?.focus(), 0)

    this.setBannerMessage(type)
  }

  setBannerMessage(type?: string) {
    let factor_text = ''
    switch (type) {
      case 'app':
        factor_text = 'your authenticator app'
        break
      case 'sms':
        factor_text = 'SMS'
        break
      default:
        factor_text = 'your authenticator app'
        break
    }

    // eslint-disable-next-line @github-ui/github-monorepo/require-set-sanitized-inner-html -- pre-existing innerHTML sink grandfathered when enabling the rule; not migrated in this rollout
    document.querySelector(
      '.wizard-step-banner .Banner-title',
      // eslint-disable-next-line i18n-text/no-en
    )!.innerHTML = `You have enabled two-factor authentication using ${factor_text}.`
  }
}
